// ItineraryAdapter: where ships are scheduled to be.
//   Demo  data/itineraries.json       generated by tools/build-data.mjs (typical routes, not published schedules)
//   Live  data/itineraries.live.json  optional, hand-curated real sailings in the same format; replaces demo per ship
import { CONFIG } from '../config.js';
import { getJSON, setSource } from './sources.js';

const base = () => CONFIG.DATA_BASE;

export class DemoItineraryAdapter {
  async load() {
    const [ships, ports, lines, routes, itin, meta] = await Promise.all(
      ['ships', 'ports', 'lines', 'routes', 'itineraries', 'meta'].map((f) => getJSON(`${base()}${f}.json`, 30000)));
    return { ships, ports, lines, routes, templates: itin.templates, sailings: itin.sailings, meta };
  }
}

export class LiveItineraryAdapter {
  // Returns { templates, sailings } or null when no curated file has been added.
  async load() {
    try {
      const j = await getJSON(`${base()}itineraries.live.json`, 8000);
      if (!j || !j.sailings || !Object.keys(j.sailings).length) return null;
      return { templates: j.templates || {}, sailings: j.sailings };
    } catch { return null; }
  }
}

export async function loadItineraries() {
  const data = await new DemoItineraryAdapter().load();
  data.realShips = new Set();
  const live = await new LiveItineraryAdapter().load();
  if (live) {
    Object.assign(data.templates, live.templates);
    for (const [ship, list] of Object.entries(live.sailings)) if (data.sailings[ship]) { data.sailings[ship] = list; data.realShips.add(ship); }
  }
  if (data.realShips.size) setSource('itineraries', 'live', `Curated schedules for ${data.realShips.size} of ${data.ships.length} ships; demo for the rest`);
  else setSource('itineraries', 'demo', 'Real ships on typical routes. Not the lines’ published schedules.', Date.parse(data.meta.anchor));
  return data;
}
